//! Embedded shell-integration scripts (bash, zsh and PowerShell).
//!
//! Faithful port of `packages/gateway/src/surfaces/shell-integration-assets.ts`.
//! That TypeScript module is itself generated by
//! `packages/gateway/scripts/embed-shell-integration.mjs` from
//! `src/surfaces/shell-integration/{bash.sh,zsh.sh,pwsh.ps1}`, and it is the
//! packaging-proof fallback for those scripts: `tsc` does not copy `.sh`/`.ps1`
//! assets into `dist/`, so a published/installed gateway (and the Tauri
//! desktop bundle) can end up without `dist/surfaces/shell-integration`.
//! Without those files the terminal silently ran with no OSC 633
//! integration, which broke prompt detection, exit codes, working-directory
//! tracking and background-command completion. The runtime writes these
//! embedded copies to a cache directory whenever the packaged files are
//! missing; `scripts/copy-shell-integration.mjs` still ships the real files
//! for users who want to read or source them directly.
//!
//! This module is pure data plus pure lookups:
//!
//! * no filesystem access, no environment lookups and, in particular, no
//!   writes — materialising a script into a cache directory is the terminal
//!   component's job, and that is also where the file mode is applied.
//! * the TypeScript module exposes no path helper, no content type and no
//!   mode/executable flag, so none is invented here. The only per-asset
//!   metadata it does expose is the record key, which is the file name; that is
//!   carried by [`ShellIntegrationAsset::file_name`] (and its alias
//!   [`ShellIntegrationAsset::key`]).
//!
//! Byte fidelity: the constants below are exactly the strings the TypeScript
//! module produces with `[...lines].join("\n")`. That join appends nothing of
//! its own, so each script keeps the trailing newline it has on disk (all three
//! end in exactly one), and no line ending is rewritten. The tests pin the
//! exact contents plus the character and UTF-8 byte counts (the TypeScript doc
//! comments quote `String.length`, i.e. UTF-16 code units, which equal the
//! character counts here because every character is in the BMP).

/// Contents of `shell-integration/bash.sh`
/// (2197 characters, 2383 UTF-8 bytes).
///
/// Identical to the TypeScript `BASH_INTEGRATION_SCRIPT`, byte for byte, including the
/// trailing newline.
pub const BASH_INTEGRATION_SCRIPT: &str = r#"#!/bin/bash
# Jait Terminal Shell Integration — Bash
# Emits OSC 633 sequences so the host can detect prompt boundaries,
# command start / finish, exit codes, and the current working directory.

# Guard against double-sourcing in this shell, not an inherited environment flag.
[[ "$JAIT_SHELL_INTEGRATION" == "1" ]] && declare -F __jait_prompt_cmd >/dev/null && return 2>/dev/null
export JAIT_SHELL_INTEGRATION=1

__jait_osc() {
  printf '\e]633;%s\a' "$1"
}

# ── Prompt (PS1) ──────────────────────────────────────────────────
# Wrap existing PS1 with A/B markers and D (exit code of last command).

__jait_prompt_cmd() {
  # $? MUST be read on the first line, and this function MUST be the first
  # entry in PROMPT_COMMAND.  Any command running ahead of it — including a
  # one-line helper like the old __jait_preexec_reset — overwrites $? with
  # its own status, which made every command report "D;0" and reported every
  # failing command as a success.
  local ec=$?
  # Re-arm the DEBUG-trap guard here rather than from a separate
  # PROMPT_COMMAND entry, for the same reason.
  __jait_preexec_fired=0
  __jait_osc "D;$ec"
  __jait_osc "P;Cwd=$PWD"
  __jait_osc "A"
}

__jait_prompt_end() {
  __jait_osc "B"
}

# Install into PROMPT_COMMAND
if [[ -z "$PROMPT_COMMAND" ]]; then
  PROMPT_COMMAND="__jait_prompt_cmd"
else
  PROMPT_COMMAND="__jait_prompt_cmd;$PROMPT_COMMAND"
fi

# Append B marker after PS1
PS1="${PS1}\[$(__jait_prompt_end)\]"

# ── Pre-exec hook (DEBUG trap) ────────────────────────────────────
# Emit C (command started) + E (command text) before each command.
__jait_preexec_fired=0

__jait_preexec() {
  # Avoid firing for PROMPT_COMMAND itself
  if [[ "$__jait_preexec_fired" == "0" ]]; then
    __jait_preexec_fired=1
    local cmd
    cmd=$(HISTTIMEFORMAT= history 1 | sed 's/^[ ]*[0-9]*[ ]*//')
    # URI-encode the command
    local encoded
    encoded=$(python3 -c "import urllib.parse,sys; print(urllib.parse.quote(sys.argv[1]))" "$cmd" 2>/dev/null || echo "$cmd")
    __jait_osc "E;$encoded"
    __jait_osc "C"
  fi
}

# The preexec flag is reset from __jait_prompt_cmd (see above) so that
# nothing runs before it and clobbers $?.
trap '__jait_preexec' DEBUG
"#;

/// Contents of `shell-integration/zsh.sh`
/// (1229 characters, 1353 UTF-8 bytes).
///
/// Identical to the TypeScript `ZSH_INTEGRATION_SCRIPT`, byte for byte, including the
/// trailing newline.
pub const ZSH_INTEGRATION_SCRIPT: &str = r#"#!/bin/zsh
# Jait Terminal Shell Integration — Zsh
# Emits OSC 633 sequences so the host can detect prompt boundaries,
# command start / finish, exit codes, and the current working directory.

# Guard against double-sourcing in this shell, not an inherited environment flag.
[[ "$JAIT_SHELL_INTEGRATION" == "1" ]] && (( $+functions[__jait_precmd] )) && return 2>/dev/null
export JAIT_SHELL_INTEGRATION=1

__jait_osc() {
  printf '\e]633;%s\a' "$1"
}

# ── precmd (runs before each prompt) ─────────────────────────────
__jait_precmd() {
  local ec=$?
  __jait_osc "D;$ec"
  __jait_osc "P;Cwd=$PWD"
  __jait_osc "A"
}

# ── preexec (runs before each command) ────────────────────────────
__jait_preexec() {
  local cmd="$1"
  # URI-encode the command (zsh has built-in parameter expansion flags)
  local encoded=${cmd//(#m)[^A-Za-z0-9_.~-]/%$(printf '%02X' "'$MATCH")}
  __jait_osc "E;$encoded"
  __jait_osc "C"
}

# Install hooks
autoload -Uz add-zsh-hook
add-zsh-hook precmd __jait_precmd
add-zsh-hook preexec __jait_preexec

# Append B marker after prompt
precmd_functions+=(__jait_precmd_end)
__jait_precmd_end() {
  # We inject B at end of PS1 via precmd since zsh evaluates PS1 each time
  PS1="${PS1}%{$(__jait_osc B)%}"
}
"#;

/// Contents of `shell-integration/pwsh.ps1`
/// (3202 characters, 3232 UTF-8 bytes).
///
/// Identical to the TypeScript `PWSH_INTEGRATION_SCRIPT`, byte for byte, including the
/// trailing newline.
pub const PWSH_INTEGRATION_SCRIPT: &str = r#"# Jait Terminal Shell Integration — PowerShell
# Emits OSC 633 sequences so the host can detect prompt boundaries,
# command start / finish, exit codes, and the current working directory.
#
# Protocol (compatible with VS Code terminal shell integration):
#   ESC]633;A BEL   — Prompt start
#   ESC]633;B BEL   — Prompt end (command line ready)
#   ESC]633;C BEL   — Command execution started
#   ESC]633;D;{exit} BEL — Command finished with exit code
#   ESC]633;E;{cmd} BEL  — The command line text (best-effort)
#   ESC]633;P;Cwd={cwd} BEL — Current working directory

# Guard against double-sourcing
if ($Global:__JaitShellIntegrationLoaded) { return }
$Global:__JaitShellIntegrationLoaded = $true
$env:JAIT_SHELL_INTEGRATION = '1'

# ESC and BEL characters — compatible with PowerShell 5.1+
$Global:__JaitESC = [char]0x1b
$Global:__JaitBEL = [char]0x07

function Global:__JaitOSC([string]$Payload) {
    return "$Global:__JaitESC]633;$Payload$Global:__JaitBEL"
}

# Store the original prompt (if any)
$Global:__JaitOrigPrompt = $function:prompt

function Global:prompt {
    # Read the completion state first — anything else in this function (or the
    # prompt it invokes) would overwrite it.
    #
    # $LASTEXITCODE only tracks native (external) programs, so a cmdlet such as
    # `echo` never clears it. Reporting it unconditionally made every command
    # after `cmd /c exit 7` look like it failed with 7. $? on the other hand
    # reflects cmdlets and scripts but carries no exit code, so combine both.
    $succeeded = $global:?
    $nativeExitCode = $global:LASTEXITCODE

    if ($succeeded) {
        $exitCode = 0
    } elseif ($nativeExitCode -is [int] -and $nativeExitCode -ne 0) {
        # Native command failure: its own exit code is the real result.
        $exitCode = $nativeExitCode
    } else {
        # Cmdlet/script failure without a native exit code.
        $exitCode = 1
    }

    # D — previous command finished with exit code
    $out = (__JaitOSC "D;$exitCode")

    # P — current working directory
    $out += (__JaitOSC "P;Cwd=$($PWD.Path)")

    # A — prompt start
    $out += (__JaitOSC "A")

    # Original prompt text (or default)
    if ($Global:__JaitOrigPrompt) {
        $out += & $Global:__JaitOrigPrompt
    } else {
        $out += "PS $($PWD.Path)> "
    }

    # B — prompt end / command-line ready
    $out += (__JaitOSC "B")

    # Preserve exit code so user scripts see it unchanged
    $global:LASTEXITCODE = $exitCode
    return $out
}

# Hook Enter key via PSReadLine to emit C (command started) + E (command text)
if (Get-Module -Name PSReadLine -ErrorAction SilentlyContinue) {
    Set-PSReadLineKeyHandler -Key Enter -ScriptBlock {
        $line = $null
        $cursor = $null
        [Microsoft.PowerShell.PSConsoleReadLine]::GetBufferState([ref]$line, [ref]$cursor)

        # E — command text (URI-encode to keep it on one OSC line)
        $encoded = [Uri]::EscapeDataString($line)
        [Console]::Write("$Global:__JaitESC]633;E;$encoded$Global:__JaitBEL")

        # C — execution started
        [Console]::Write("$Global:__JaitESC]633;C$Global:__JaitBEL")

        [Microsoft.PowerShell.PSConsoleReadLine]::AcceptLine()
    }
}
"#;

/// Double-sourcing guard that opens `shell-integration/bash.sh`.
///
/// The script returns early when it sees this line and
/// [`BASH_INTEGRATION_SCRIPT`]'s helper is already defined, which is how the
/// integration stays idempotent when an rc file is sourced twice.
pub const BASH_INSTALL_MARKER: &str = r#"[[ "$JAIT_SHELL_INTEGRATION" == "1" ]] && declare -F __jait_prompt_cmd >/dev/null && return 2>/dev/null"#;

/// Double-sourcing guard that opens `shell-integration/zsh.sh`.
///
/// The script returns early when the integration was already loaded in this
/// shell and its helper is already defined.
pub const ZSH_INSTALL_MARKER: &str = r#"[[ "$JAIT_SHELL_INTEGRATION" == "1" ]] && (( $+functions[__jait_precmd] )) && return 2>/dev/null"#;

/// Double-sourcing guard that opens `shell-integration/pwsh.ps1`.
///
/// The script returns early when the `__JaitShellIntegrationLoaded` flag is
/// already set on the global scope of this session.
pub const PWSH_INSTALL_MARKER: &str = r#"if ($Global:__JaitShellIntegrationLoaded) { return }"#;

/// One embedded shell-integration script.
///
/// Names the asset instead of passing the raw `&str` keys around the way the
/// TypeScript code does (`SHELL_INTEGRATION_ASSETS[name]`). The key set is
/// exactly the TypeScript record key set, matched case-sensitively.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum ShellIntegrationAsset {
    /// `bash.sh`
    Bash,
    /// `zsh.sh`
    Zsh,
    /// `pwsh.ps1`
    Pwsh,
}

impl ShellIntegrationAsset {
    /// Every asset, in the same order the TypeScript record declares its keys.
    pub const ALL: [Self; 3] = [Self::Bash, Self::Zsh, Self::Pwsh];

    /// Every asset, in the same order the TypeScript record declares its keys.
    pub fn all() -> &'static [Self] {
        &Self::ALL
    }

    /// Exact, case-sensitive key lookup.
    ///
    /// Mirrors `SHELL_INTEGRATION_ASSETS[key]`: a key that the TypeScript
    /// record does not have yields `undefined` there and `None` here, and no
    /// default is substituted. That includes the empty string.
    pub fn from_key(key: &str) -> Option<Self> {
        match key {
            "bash.sh" => Some(Self::Bash),
            "zsh.sh" => Some(Self::Zsh),
            "pwsh.ps1" => Some(Self::Pwsh),
            _ => None,
        }
    }

    /// The TypeScript record key of this asset, which is also its file name.
    pub fn key(self) -> &'static str {
        self.file_name()
    }

    /// File name of this asset inside `shell-integration/`.
    pub fn file_name(self) -> &'static str {
        match self {
            Self::Bash => "bash.sh",
            Self::Zsh => "zsh.sh",
            Self::Pwsh => "pwsh.ps1",
        }
    }

    /// Embedded contents of this asset, byte for byte as in TypeScript.
    pub fn content(self) -> &'static str {
        match self {
            Self::Bash => BASH_INTEGRATION_SCRIPT,
            Self::Zsh => ZSH_INTEGRATION_SCRIPT,
            Self::Pwsh => PWSH_INTEGRATION_SCRIPT,
        }
    }

    /// Line the script uses to detect that a copy is already installed.
    ///
    /// The TypeScript module has no such helper because the guard only ever
    /// runs inside the shell; the Rust side needs the marker as data so a
    /// caller can tell an already-installed rc file from a fresh one.
    pub fn install_marker(self) -> &'static str {
        match self {
            Self::Bash => BASH_INSTALL_MARKER,
            Self::Zsh => ZSH_INSTALL_MARKER,
            Self::Pwsh => PWSH_INSTALL_MARKER,
        }
    }

    /// Whether `existing` (e.g. the contents of an rc file) already carries the
    /// installed block for this asset.
    pub fn is_already_installed(self, existing: &str) -> bool {
        existing.contains(self.install_marker())
    }
}

impl std::fmt::Display for ShellIntegrationAsset {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.file_name())
    }
}

/// Map of integration script filename -> embedded contents.
///
/// Mirrors the TypeScript `SHELL_INTEGRATION_ASSETS` object literal, including
/// key order: `bash.sh`, `zsh.sh`, `pwsh.ps1`.
pub const SHELL_INTEGRATION_ASSETS: [(&str, &str); 3] = [
    ("bash.sh", BASH_INTEGRATION_SCRIPT),
    ("zsh.sh", ZSH_INTEGRATION_SCRIPT),
    ("pwsh.ps1", PWSH_INTEGRATION_SCRIPT),
];

/// Mirrors `SHELL_INTEGRATION_ASSETS[key]`.
///
/// Unknown and empty keys yield `None`, exactly like the `undefined` the
/// TypeScript index access produces; nothing is defaulted.
pub fn shell_integration_asset(key: &str) -> Option<&'static str> {
    ShellIntegrationAsset::from_key(key).map(ShellIntegrationAsset::content)
}

